'use client';
import { useState, useRef, useEffect } from 'react';
import Link from 'next/link';
import { services } from './services';
export default function SiteHeader() {
  const [mobile, setMobile] = useState(false);
  const [open, setOpen] = useState(null);
  const header = useRef(null);
  const toggle = useRef(null);
  useEffect(() => {
    function close(event) { if (!header.current?.contains(event.target)) { setOpen(null); setMobile(false); } }
    document.addEventListener('pointerdown', close);
    return () => document.removeEventListener('pointerdown', close);
  }, []);
  function dropdown(label, entries) {
    return <div className="nav-dropdown" onMouseEnter={() => { if (window.matchMedia('(hover: hover)').matches) setOpen(label); }} onMouseLeave={() => { if (window.matchMedia('(hover: hover)').matches) setOpen(null); }} onBlur={e => { if (!e.currentTarget.contains(e.relatedTarget)) setOpen(null); }}><button className="dropdown-toggle" aria-expanded={open === label} aria-controls={`dropdown-${label}`} onClick={() => setOpen(open === label ? null : label)}>{label}<span aria-hidden="true">⌄</span></button><div id={`dropdown-${label}`} className="dropdown-panel" hidden={open !== label}>{entries.map(([title, href]) => <Link key={href} href={href} onClick={() => { setOpen(null); setMobile(false); }}>{title}</Link>)}</div></div>;
  }
  return <header ref={header} className="header site-header" onKeyDown={e => { if (e.key === 'Escape') { const button = e.target.closest('.nav-dropdown')?.querySelector('button'); setOpen(null); if (button) button.focus(); else { setMobile(false); toggle.current?.focus(); } } }}><div className="nav-wrap"><Link className="brand" href="/" aria-label="Family Dental Clinic home"><img className="brand-logo" src="/images/family-dental-logo.svg" alt="" width="72" height="48" /><span>family dental<span className="brand-sub">CLINIC · MIRPUR</span></span></Link><button ref={toggle} className={`menu-button ${mobile ? 'is-open' : ''}`} aria-label="Toggle navigation" aria-expanded={mobile} aria-controls="site-navigation" onClick={() => setMobile(!mobile)}><span /><span /></button><nav id="site-navigation" className={`site-navigation ${mobile ? 'is-open' : ''}`} aria-label="Main navigation"><Link href="/" onClick={() => setMobile(false)}>Home</Link>{dropdown('Pages', [['About our clinic', '/about'], ['Services', '/services'], ['FAQ', '/faq']])}{dropdown('Services', services.map(s => [s.title, `/services/${s.slug}`]))}<Link href="/#contact" onClick={() => setMobile(false)}>Contact</Link></nav><a className="button nav-cta" href="tel:+923203771995">Call / Book a visit ↗</a></div></header>;
}
